package com.skillsync.user;

import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service public class RoadmapTaskService {
    private final RoadmapTaskRepository tasks;
    public RoadmapTaskService(RoadmapTaskRepository tasks){this.tasks=tasks;}
    @Transactional public List<RoadmapTask> ensure(User user,String career,List<String> gaps,List<String> partial){
        List<RoadmapTask> existing=tasks.findAllByUserIdAndCareerNameOrderByWeekIndexAscIdAsc(user.getId(),career);
        Map<String,RoadmapTask> existingByKey=new HashMap<>();existing.forEach(t->existingByKey.put(t.getSkillName()+"|"+t.getPhase(),t));
        LinkedHashSet<String> skills=new LinkedHashSet<>(gaps);skills.addAll(partial);int week=0;
        for(String skill:skills){week++;boolean advanced=partial.contains(skill)&&!gaps.contains(skill);String prefix=advanced?"Extend ":"Learn ";
            upsert(user,career,skill,"LEARN",prefix+skill+" foundations",learnDescription(skill,advanced),week,existingByKey);
            upsert(user,career,skill,"PRACTICE","Practice "+skill,practiceDescription(skill,advanced),week,existingByKey);
            upsert(user,career,skill,"BUILD","Build with "+skill,buildDescription(skill,career),week,existingByKey);
            upsert(user,career,skill,"PROVE","Prove "+skill,"Publish or save the deliverable, then add it under Skills profile → Add evidence. Include your own contribution, tools used, outcome, and a working link where possible; never claim work you did not do.",week,existingByKey);
        }
        return tasks.findAllByUserIdAndCareerNameOrderByWeekIndexAscIdAsc(user.getId(),career);
    }
    private void upsert(User user,String career,String skill,String phase,String title,String desc,int week,Map<String,RoadmapTask> existing){RoadmapTask task=existing.get(skill+"|"+phase);if(task==null)tasks.save(new RoadmapTask(user,career,skill,phase,title,desc,week));else if(!task.getTitle().equals(title)||!task.getDescription().equals(desc)||task.getWeekIndex()!=week)task.refreshGuidance(title,desc,week);}
    private String learnDescription(String skill,boolean advanced){return switch(skill){case "Docker"->"Read the official getting-started guide. Explain images, containers, ports, volumes, and environment variables in your own notes.";case "Statistics"->"Use the OpenIntro chapters on distributions, sampling, confidence intervals, and tests. Write down when each method is appropriate and its assumptions.";case "System Design"->"Study requirements, APIs, data models, caching, queues, and failure handling. Sketch a small system and label its trade-offs.";case "Cloud Computing"->"Study compute, storage, networking, identity, and cost basics in the linked cloud learning material. Draw how a simple web app uses them.";case "Cybersecurity"->"Review threat modeling, authentication, authorization, secure defaults, and common web risks. Keep a checklist of mitigations.";case "SQL"->"Study joins, grouping, constraints, indexes, and transactions. Create a small schema and explain why each relationship exists.";case "Data Engineering"->"Map an ingestion-to-storage-to-quality pipeline. Note batch versus streaming trade-offs, data contracts, and failure recovery.";case "Machine Learning"->"Study a baseline model, train/test separation, leakage, evaluation metrics, and error analysis before tuning anything.";case "AI Literacy","Prompt Engineering","LLM APIs"->"Study model limitations, structured prompting, evaluation, privacy, and safe failure handling. Record examples where output needs verification.";default->(advanced?"Build on what you already know: study advanced patterns, edge cases, and trade-offs for ":"Study the foundations and common workflows for ")+skill+". Write five key concepts and one example of when each is useful.";};}
    private String practiceDescription(String skill,boolean advanced){return switch(skill){case "Docker"->"Containerize a small web service, publish a port, mount persistent data, and inspect logs. Record the exact commands and one issue you resolved.";case "Statistics"->"Choose a public dataset; calculate summary statistics and one confidence interval, then explain uncertainty without overstating causation.";case "System Design"->"Design a URL shortener or course-registration service. Estimate load, identify bottlenecks, and compare two storage or caching choices.";case "SQL"->"Write and explain at least five queries using joins, aggregation, filtering, and a subquery against your sample schema.";case "Git"->"Create a branch, make focused commits, resolve a small merge conflict in a practice repository, and document the workflow.";case "UX Research"->"Draft neutral interview questions, conduct a small consent-based usability exercise, and summarize themes without identifying participants.";case "Business Analysis"->"Turn a fictional stakeholder request into user stories, acceptance criteria, and a simple process or data-flow diagram.";case "Communication","Presentation Skills"->"Explain one technical or business idea in a three-minute presentation; ask a peer for one specific improvement and revise it.";default->"Complete three progressively harder exercises in "+skill+". Keep the inputs, your result, and a short explanation of mistakes or trade-offs."+(advanced?" Include at least one edge case.":"");};}
    private String buildDescription(String skill,String career){return switch(skill){case "Docker"->"Containerize a small "+career+" demo with a reproducible build, health check, and concise README. Do not include secrets in the image.";case "Statistics","Data Visualization"->"Create a short analysis of a public dataset relevant to "+career+" with a clear chart, method notes, limitations, and source link.";case "System Design"->"Produce a one-page architecture for a small "+career+"-related service, including API, data flow, one failure mode, and an explicit trade-off.";case "UX Research"->"Create a small research brief for a "+career+"-related product: question, method, anonymized findings, and one evidence-based recommendation.";case "Technical Writing","Content Strategy"->"Write a concise how-to or decision guide for a "+career+"-related task, with audience, steps, examples, and a review checklist.";case "Business Analysis","Market Research","Product Strategy"->"Create a one-page case for a "+career+"-related improvement: user need, evidence, options, recommendation, success measure, and risks.";case "Collaboration","Communication","Presentation Skills"->"Run a small, consent-based peer review of a "+career+" deliverable; record feedback themes and show what you changed.";default->"Build a small, working "+career+"-relevant deliverable that uses "+skill+". Include a README, setup steps, a test or validation, and what you would improve next.";};}
    @Transactional public void mark(User user,Long id,boolean completed){RoadmapTask task=tasks.findByIdAndUserId(id,user.getId()).orElseThrow();task.setCompleted(completed);tasks.save(task);}
}
